/* SDK adapters generated by extract_playlist_engine.py. */
/* R80 main-Browse playlist reorder: the knob gesture, wired (OQ_PLAYLIST_REORDER).
 *
 * AZ-style: hold the browse knob on a track of a USB playlist sorted by "#"
 * ascending to pick it up, turn to move it, press to drop it, hold again to
 * cancel. The drop queues one request for the library thread
 * (native_playlist_reorder.h); stock browsing is untouched otherwise.
 *
 * Message thread (JUCE) only. Stock EP136 1.32 entry points:
 *   KNOBEV   0x1670658  lambda(BrowseView **capture, const int *ev): ev 1 click,
 *                       ev 2 long press (stock: quick scroll). Inline hook.
 *   KNOBTURN 0x16707f8  BrowseView vt+0x198 (view, ?, int delta). Inline hook;
 *                       stock still moves its cursor, which marks the drop row.
 *   cell     TrackListWidget model vt 0x27ce070 +0x28 (thunk 0x1886680 ->
 *                       refreshComponentForCell(widget, row, col, sel, existing)).
 *                       Slot patch; while a track is held, display row r draws
 *                       data row pg_data_row(r): the preview. Nothing is written.
 *   paint    the same vtable +0x90 (thunk 0x188bc10 -> TrackListWidget paintCell
 *                       (widget, g, row, col, w, h, sel, extra)): the painted
 *                       columns (#, BPM, Key, ...) get the same remap. Slot patch.
 *   widget   TrackListWidget vt 0x27cdef0: +0x70 meow::TouchableTableListBox
 *                       (vt 0x29b9758, model at +0x140 == widget+0x30), +0x2e8
 *                       rows, +0x2d0 ring of 27 x 0x78 entries (+0 row, +0x70 not
 *                       ready, +0x20 the "#" column text). QEMU-checked.
 * Identity: the "#" text of every ready ring row must equal row+1 (the list is
 * "#" ascending, so a display row is a stored position), and the newest native
 * list-state observation (native_playlist_memory.h) must name the playlist
 * and the held track. The library thread re-reads the DB and refuses (STALE)
 * unless it still has exactly those rows with the held track at `from`.
 *
 * Saving: the request is claimed by the next library message on that USB.
 * Stock sends one for BACK, entering a list or selecting a playlist, so the
 * banner asks for BACK. The cache drop then makes the list re-query. */
#ifndef OQ_PLAYLIST_REORDER_KNOB_H
#define OQ_PLAYLIST_REORDER_KNOB_H

#define PLK_KNOBEV_FN 0x1670658u
#define PLK_KNOBTURN_FN 0x16707f8u
#define PLK_CELL_SLOT 0x27ce098u
#define PLK_CELL_THUNK 0x1886680u
#define PLK_PAINT_SLOT 0x27ce100u
#define PLK_PAINT_THUNK 0x188bc10u
#define PLK_WIDGET_VT 0x27cdef0u
#define PLK_WIDGET_MODEL 0x30u
#define PLK_WIDGET_LIST 0x70u
#define PLK_WIDGET_RING 0x2d0u
#define PLK_WIDGET_ROWS 0x2e8u
#define PLK_LIST_VT 0x29b9758u
#define PLK_LIST_MODEL 0x140u
#define PLK_RING_N 27
#define PLK_RING_STRIDE 0x78u
#define PLK_LB_SELECTED_ROW 0x1dfd290u /* juce::ListBox::getSelectedRow(int) */
#define PLK_LB_UPDATE 0x1dfad60u       /* juce::ListBox::updateContent() */
#define PLK_REPAINT 0x209c3d0u         /* juce::Component::repaint() */
/* BrowseView predicates KNOBEV tests before its ev 2 quick-scroll branch */
#define PLK_VIEW_OVERLAY_A 0x1669568u
#define PLK_VIEW_MODE_IS 0x1669728u
#define PLK_VIEW_OVERLAY_B 0x16693b8u
#define PLK_VIEW_OVERLAY_C 0x1669520u
#define PLK_SAVE_TIMEOUT_MS 120000

static struct pg plk_g;            /* the gesture */
static uintptr_t plk_seen;          /* last TrackListWidget whose cells were refreshed */
static struct {
    uintptr_t widget;
    uint64_t media;
    uint32_t playlist, track;
    int rows, pending_from, pending_to; /* pending_*: preview kept until the save ends */
    int pending;
    uint64_t pending_ms;
} plk_cur;
static unsigned plk_installed;
static void (*plk_ev_original)(void *, const int *);
static int (*plk_turn_original)(void *, int, int);
static void *(*plk_cell_original)(void *, int, int, int, void *);
static void (*plk_paint_original)(void *, void *, int, int, int, int, int, int);

/* diagnostics: the last 48 gesture events, message thread writes */
struct plk_event { uint64_t ms; char kind; int a, b, c; };
static struct plk_event plk_events[48];
static unsigned plk_event_next, plk_grabs, plk_drops, plk_cancels, plk_refusals, plk_results;
static int plk_last_result = 99;
static void plk_note(char kind, int a, int b, int c) {
    plk_events[plk_event_next++ % 48] = (struct plk_event){rt_now() / 1000000, kind, a, b, c};
}

static int plk_armed(void) {
    return plk_installed == 15 && __atomic_load_n(&editor_authorized,__ATOMIC_ACQUIRE);
}
static uint64_t plk_ms(void) { return rt_now() / 1000000; }
/* The list of a live TrackListWidget, or 0. */
static uintptr_t plk_list(uintptr_t w) {
    if (!w || (w & 7) || *(const uintptr_t *) w != PLK_WIDGET_VT)
        return 0;
    uintptr_t l = *(const uintptr_t *) (w + PLK_WIDGET_LIST);
    if (!l || (l & 7) || *(const uintptr_t *) l != PLK_LIST_VT ||
        *(const uintptr_t *) (l + PLK_LIST_MODEL) != w + PLK_WIDGET_MODEL)
        return 0;
    return l;
}
static int plk_selected(uintptr_t list) { return ((int (*)(uintptr_t, int)) PLK_LB_SELECTED_ROW)(list, 0); }
/* updateContent re-runs refreshComponentForCell (the title component), but
 * JUCE repaints a row's painted columns only when its row or selection
 * changed, so a cancel left #/BPM/Key showing the preview (QEMU). Repaint all. */
static void plk_refresh(uintptr_t list) {
    ((void (*)(uintptr_t)) PLK_LB_UPDATE)(list);
    ((void (*)(uintptr_t)) PLK_REPAINT)(list);
}
/* juce::String text of a ring field; "" when absent. */
static const char *plk_text(uintptr_t field) {
    const char *t = *(const char *const *) field;
    return t ? t : "";
}
/* 1 when every ready ring row shows "#" == row+1 and `from` is among them. */
static int plk_hash_ascending(uintptr_t w, int rows, int from) {
    uintptr_t ring = *(const uintptr_t *) (w + PLK_WIDGET_RING),
              end = *(const uintptr_t *) (w + PLK_WIDGET_RING + 8);
    if (!ring || end < ring || (end - ring) % PLK_RING_STRIDE || (end - ring) / PLK_RING_STRIDE > PLK_RING_N)
        return 0;
    int checked = 0, saw_from = 0;
    for (uintptr_t e = ring; e < end; e += PLK_RING_STRIDE) {
        int row = *(const int *) e;
        if (row < 0 || row >= rows || *(const unsigned char *) (e + 0x70))
            continue;
        const char *t = plk_text(e + 0x20);
        int v = 0, digits = 0;
        for (; *t >= '0' && *t <= '9' && digits < 7; t++, digits++)
            v = v * 10 + (*t - '0');
        if (!digits || *t || v != row + 1)
            return 0;
        checked++;
        saw_from |= row == from;
    }
    return checked >= 2 && saw_from;
}
/* The newest native list-state observation for the active media. */
static int plk_position(struct oqmod_playlist_position *out){return editor_io.position(out);}
static int plk_db_for(uint64_t media,char *db,size_t cap){
    struct oqmod_library_source source;
    if(!editor_io.source_for_media(media,&source))return 0;
    snprintf(db,cap,"%s",source.db);return 1;
}
static void plk_banner(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
static void plk_banner(const char *fmt, ...) {
    char line[96];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(line, sizeof line, fmt, ap);
    va_end(ap);
    editor_io.notice(line, 8000);
    olog("playlist edit: %s\n", line);
}
static void plk_cancel(const char *why) {
    if (pg_cancel(&plk_g)) {
        plk_cancels++;
        plk_note('C', 0, 0, 0);
        uintptr_t list = plk_list(plk_cur.widget);
        if (list)
            plk_refresh(list);
        plk_banner("%s", why);
    }
}

/* ---- gesture ---- */
static int plk_try_grab(void *view) {
    int st = __atomic_load_n(&g_plr_state, __ATOMIC_ACQUIRE);
    if (st == PLR_PENDING || st == PLR_RUNNING || plk_cur.pending) {
        plk_banner("Previous move is not saved yet: press BACK to save it");
        return 0;
    }
    /* stock reaches its ev 2 quick-scroll branch only in list mode 2 with no
     * overlay shown; anywhere else the long press stays stock's */
    int two = 2;
    if (((int (*)(void *)) PLK_VIEW_OVERLAY_A)(view) & 0xff ||
        !(((int (*)(void *, const int *)) PLK_VIEW_MODE_IS)(view, &two) & 0xff) ||
        ((int (*)(void *)) PLK_VIEW_OVERLAY_B)(view) & 0xff || ((int (*)(void *)) PLK_VIEW_OVERLAY_C)(view) & 0xff)
        return 0;
    uintptr_t w = plk_seen, list = plk_list(w);
    if (!list)
        return 0;
    int rows = *(const int *) (w + PLK_WIDGET_ROWS), from = plk_selected(list);
    struct oqmod_playlist_position p = {0};
    char db[160];
    const char *why = 0;
    if (rows < 2 || rows > PLR_MAX || from < 0 || from >= rows)
        why = "Playlist editing: no track selected";
    else if (!plk_position(&p))
        why = "Playlist editing: open a USB playlist first";
    else if (!plk_hash_ascending(w, rows, from))
        why = "Playlist editing: sort the playlist by # (ascending) first";
    else if ((int) p.cursor != from)
        why = "Playlist editing: selection not confirmed, turn the knob and retry";
    else if (!plk_db_for(p.media, db, sizeof db))
        why = "Playlist editing: USB library not found";
    plk_note('H', from, rows, why ? 0 : (int) p.playlist);
    if (why) {
        plk_refusals++;
        plk_banner("%s", why);
        return 0;
    }
    if (!pg_knob_hold(&plk_g, from, rows, 1))
        return 0;
    plk_cur.widget = w;
    plk_cur.media = p.media;
    plk_cur.playlist = (uint32_t) p.playlist;
    plk_cur.track = (uint32_t) p.track;
    plk_cur.rows = rows;
    snprintf(g_plr_db, sizeof g_plr_db, "%s", db);
    plk_grabs++;
    plk_banner("Moving #%d: turn to move, press to drop, hold to cancel", from + 1);
    return 1;
}
static void plk_drop(void) {
    int from, to;
    uintptr_t list = plk_list(plk_cur.widget);
    int sel = list && plk_cur.widget == plk_seen ? plk_selected(list) : -1;
    if (sel >= 0 && sel < plk_g.rows)
        plk_g.to = sel; /* the highlighted row, settled */
    if (plk_g.to == plk_g.from) {
        plk_banner("Turn to move, press to drop, hold to cancel");
        return;
    }
    if (!pg_knob_press(&plk_g) || !pg_take_commit(&plk_g, &from, &to)) {
        plk_cancel("Move cancelled");
        return;
    }
    memset(&g_plr_req, 0, sizeof g_plr_req);
    g_plr_req.playlist_id = plk_cur.playlist;
    g_plr_req.grabbed = plk_cur.track;
    g_plr_req.rows = (unsigned) plk_cur.rows;
    g_plr_req.from = (unsigned) from;
    g_plr_req.to = (unsigned) to;
    plk_cur.pending = 1;
    plk_cur.pending_from = from;
    plk_cur.pending_to = to;
    plk_cur.pending_ms = plk_ms();
    __atomic_store_n(&g_plr_result, PLR_BAD, __ATOMIC_RELAXED);
    __atomic_store_n(&g_plr_state, PLR_PENDING, __ATOMIC_RELEASE);
    plk_drops++;
    plk_note('D', from, to, (int) plk_cur.playlist);
    editor_io.notice("", 0);
    char line[96];
    snprintf(line, sizeof line, "#%d -> #%d. Press BACK to save (hold knob = undo)", from + 1, to + 1);
    editor_io.notice(line, PLK_SAVE_TIMEOUT_MS);
    olog("playlist edit: drop playlist=%u track=%u from=%d to=%d rows=%d db=%s\n", plk_cur.playlist,
         plk_cur.track, from, to, plk_cur.rows, g_plr_db);
}

/* ---- hooks ---- */
static int plk_remap(uintptr_t w, int row);
static void plk_ev_hook(void *capture, const int *evp) {
    int ev = evp ? *evp : -1;
    if (pg_active(&plk_g)) {
        plk_note('E', ev, plk_g.from, plk_g.to);
        if (ev == 2)
            plk_cancel("Move cancelled");
        else if (ev == 1)
            plk_drop(); /* a drop where it started keeps holding */
        return; /* every knob event belongs to the move while a track is held */
    }
    if (ev == 2 && plk_cur.pending && __atomic_load_n(&g_plr_state, __ATOMIC_ACQUIRE) == PLR_PENDING) {
        int want = PLR_PENDING; /* undo a drop that no library message claimed yet */
        if (__atomic_compare_exchange_n(&g_plr_state, &want, PLR_IDLE, 0, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
            plk_cur.pending = 0;
            plk_note('U', 0, 0, 0);
            uintptr_t list = plk_list(plk_cur.widget);
            if (list && list == plk_list(plk_seen))
                plk_refresh(list);
            plk_banner("Move undone: nothing was written");
            return;
        }
    }
    if (ev == 2 && plk_armed() && capture && plk_try_grab(*(void **) capture))
        return;
    plk_ev_original(capture, evp);
}
static int plk_turn_hook(void *view, int a, int delta) {
    if (!pg_active(&plk_g))
        return plk_turn_original(view, a, delta);
    uintptr_t list = plk_list(plk_cur.widget);
    if (!list || plk_cur.widget != plk_seen) {
        plk_cancel("Move cancelled: the list closed");
        return plk_turn_original(view, a, delta);
    }
    /* Stock moves its cursor by the same delta, but asynchronously (QEMU: the
     * selection read right after the call still shows the previous row). So
     * start from the settled selection and add the delta; the drop re-reads it. */
    int sel = plk_selected(list);
    if (sel >= 0 && sel < plk_g.rows)
        plk_g.to = sel;
    int r = plk_turn_original(view, a, delta);
    pg_knob_turn(&plk_g, delta);
    plk_note('T', delta, sel, plk_g.to);
    plk_refresh(list);
    plk_banner("Moving #%d to #%d: press to drop, hold to cancel", plk_g.from + 1, plk_g.to + 1);
    return r;
}
static void *plk_cell_hook(void *model, int row, int col, int selected, void *existing) {
    uintptr_t w = (uintptr_t) model - PLK_WIDGET_MODEL;
    if (*(const uintptr_t *) w == PLK_WIDGET_VT)
        plk_seen = w;
    return plk_cell_original(model, plk_remap(w, row), col, selected, existing);
}

static int plk_remap(uintptr_t w, int row) {
    if (w != plk_cur.widget)
        return row;
    if (pg_active(&plk_g))
        return pg_data_row(&plk_g, row);
    if (plk_cur.pending) {
        struct pg view = {.state = PG_GRABBED, .from = plk_cur.pending_from, .to = plk_cur.pending_to};
        return pg_data_row(&view, row);
    }
    return row;
}
static void plk_paint_hook(void *model, void *g, int row, int col, int w, int h, int sel, int extra) {
    plk_paint_original(model, g, plk_remap((uintptr_t) model - PLK_WIDGET_MODEL, row), col, w, h, sel, extra);
}

/* mm_tick: arming changes, the library thread's result, the save timeout. */
static void plk_tick(void) {
    if (pg_active(&plk_g) && !plk_armed())
        plk_cancel("Move cancelled: Playlist Editing is off");
    if (!plk_cur.pending)
        return;
    int st = __atomic_load_n(&g_plr_state, __ATOMIC_ACQUIRE);
    if (st == PLR_PENDING && plk_ms() - plk_cur.pending_ms > PLK_SAVE_TIMEOUT_MS) {
        int want = PLR_PENDING;
        if (__atomic_compare_exchange_n(&g_plr_state, &want, PLR_IDLE, 0, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
            plk_cur.pending = 0;
            plk_note('X', 0, 0, 0);
            plk_banner("Move NOT saved (no library activity): nothing was written");
        }
        return;
    }
    if (st != PLR_DONE)
        return;
    int r = __atomic_load_n(&g_plr_result, __ATOMIC_RELAXED), pdb = __atomic_load_n(&g_plr_pdb_result, __ATOMIC_RELAXED),
        backup = __atomic_load_n(&g_plr_backup_result, __ATOMIC_RELAXED);
    plk_cur.pending = 0;
    plk_last_result = r;
    plk_results++;
    plk_note('R', r, pdb, backup);
    __atomic_store_n(&g_plr_state, PLR_IDLE, __ATOMIC_RELEASE);
    uintptr_t list = plk_list(plk_cur.widget);
    if (list && list == plk_list(plk_seen))
        plk_refresh(list);
    static const char *const why[] = {"", "", "bad request", "unexpected firmware state", "library busy",
                                      "playlist changed", "write failed, rolled back", "check failed, rolled back",
                                      "check after save failed", "playlist too long", "USB too full", "backup failed"};
    if (r == PLR_OK && pdb == PDBM_OK)
        plk_banner("Saved #%d -> #%d (%s%u ms). Re-open the playlist to see it", plk_cur.pending_from + 1,
                   plk_cur.pending_to + 1, backup == PLB_OK ? "backup made, " : "", g_plr_ms);
    else if (r == PLR_OK)
        plk_banner("Saved in the library; export.pdb not updated (%d)", pdb);
    else
        plk_banner("NOT saved: %s (%d). Nothing was written", r < 0 && -r <= 10 ? why[-r + 1] : "error", r);
    olog("playlist edit: result=%d pdb=%d backup=%d ms=%u playlist=%u\n", r, pdb, backup, g_plr_ms, plk_cur.playlist);
}

/* Constructor time. 15 when all four hooks are in; anything less arms nothing. */
static unsigned plk_install(void) {
    static const uint32_t ev_words[4] = {0xa9bc7bfdu, 0x910003fdu, 0xa90153f3u, 0xaa0003f3u};
    static const uint32_t turn_words[4] = {0xa9bc7bfdu, 0x910003fdu, 0xa90153f3u, 0x2a0203f4u};
    if (memcmp((const void *) PLK_KNOBEV_FN, ev_words, sizeof ev_words) ||
        memcmp((const void *) PLK_KNOBTURN_FN, turn_words, sizeof turn_words) ||
        *(const uintptr_t *) PLK_CELL_SLOT != PLK_CELL_THUNK || *(const uintptr_t *) PLK_PAINT_SLOT != PLK_PAINT_THUNK ||
        *(const uint32_t *) PLK_LB_SELECTED_ROW == 0 || *(const uint32_t *) PLK_LB_UPDATE == 0 ||
        *(const uint32_t *) PLK_REPAINT != 0xa9be7bfdu)
        return 0;
    if (patch_slot(PLK_CELL_SLOT, (void *) plk_cell_hook, (void **) &plk_cell_original) == 1)
        plk_installed |= 1;
    if (plk_installed == 1 && patch_slot(PLK_PAINT_SLOT, (void *) plk_paint_hook, (void **) &plk_paint_original) == 1)
        plk_installed |= 8;
    if (plk_installed == 9 && inline_hook(PLK_KNOBTURN_FN, (void *) plk_turn_hook, (void **) &plk_turn_original) == 1)
        plk_installed |= 2;
    if (plk_installed == 11 && inline_hook(PLK_KNOBEV_FN, (void *) plk_ev_hook, (void **) &plk_ev_original) == 1)
        plk_installed |= 4;
    return plk_installed;
}
static void plk_report(FILE *out) {
    fprintf(out, "playlist_edit installed=%u armed=%d grabs=%u drops=%u cancels=%u refusals=%u results=%u last_result=%d "
                 "state=%d pdb=%d backup=%d ms=%u db=%s\n",
            plk_installed, plk_armed(), plk_grabs, plk_drops, plk_cancels, plk_refusals, plk_results, plk_last_result,
            __atomic_load_n(&g_plr_state, __ATOMIC_ACQUIRE), __atomic_load_n(&g_plr_pdb_result, __ATOMIC_RELAXED),
            __atomic_load_n(&g_plr_backup_result, __ATOMIC_RELAXED), g_plr_ms, g_plr_db);
    for (unsigned n = plk_event_next, i = n > 48 ? n - 48 : 0; i < n; i++)
        fprintf(out, "playlist_edit_event=%u ms=%llu kind=%c a=%d b=%d c=%d\n", i,
                (unsigned long long) plk_events[i % 48].ms, plk_events[i % 48].kind, plk_events[i % 48].a,
                plk_events[i % 48].b, plk_events[i % 48].c);
}
#endif
